<script setup lang="ts">
/**
 * A collapsible section showing the model's reasoning (`design/components/reasoning-disclosure.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/reasoning-disclosure.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/collapsible'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/reasoning-disclosure.module.css'

export interface ReasoningDisclosureProps {
  /**
   * Whether it starts open, closed by default so the reasoning is available but out of the way.
   */
  defaultOpen?: boolean
  /**
   * The trigger's text in the app's words, such as "Thinking…" or "Thought for 12 seconds".
   */
  label: string
  /**
   * The controlled open state, paired with `onOpenChange` as in Radix.
   */
  open?: boolean
  /**
   * Whether the model is still reasoning, which spins the mark and sets `aria-busy` on the root.
   */
  streaming?: boolean
}

defineOptions({ name: 'ReasoningDisclosure', inheritAttrs: false })

const props = withDefaults(defineProps<ReasoningDisclosureProps>(), {
  defaultOpen: false,
  open: undefined,
  streaming: false,
})
const emit = defineEmits<{ openChange: [open: boolean] }>()
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const uid = useId()
const trigger = useTemplateRef<HTMLElement>('trigger')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open,
    defaultOpen: props.defaultOpen,
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ReasoningDisclosure',
    element: () => trigger.value,
    state: () => ({ expanded: api.value.open, streaming: props.streaming }),
    actions: { expand: () => api.value.setOpen(true), collapse: () => api.value.setOpen(false) },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    v-bind="api.getRootProps()"
    :class="styles.root"
    :data-streaming="streaming ? '' : undefined"
    :aria-busy="streaming ? true : undefined"
    data-member="reasoning-disclosure"
  >
    <!-- trigger -->
    <button ref="trigger" v-bind="api.getTriggerProps()" :class="styles.trigger">
      <!-- mark -->
      <span :class="[styles.mark, streaming ? styles.spinning : undefined]">
        <Icon :name="streaming ? 'loading' : 'reasoning'" size="sm" />
      </span>
      <!-- label -->
      <span :class="styles.label">
        {{ label }}
      </span>
      <!-- chevron -->
      <span :class="styles.chevron">
        <Icon name="down" size="sm" />
      </span>
    </button>
    <!-- content -->
    <div
      v-bind="api.getContentProps()"
      :class="styles.content"
      :style="{
        '--radix-collapsible-content-height': Object(api.getContentProps().style)['--height'],
      }"
    >
      <div :class="styles.inner">
        <slot />
      </div>
    </div>
  </div>
</template>
